/**
 * react-native stub — hooks/node_modules/ test double.
 *
 * Platform.OS = 'ios' so useNotifications.ts's Platform.OS !== 'web' guards
 * pass, letting the notification scheduling and cancellation paths run in
 * tests (required by syncActivationWithCatalogue).
 *
 * Metro never sees this file: hooks/node_modules/ is in metro.config.js
 * blockList, so Metro always falls through to the real react-native package.
 */

export const Platform = {
  OS: 'ios',
  select: (spec) => spec.ios ?? spec.default ?? undefined,
};

export default { Platform };
